# -*- coding: utf-8 -*-
"""Original NOV lessons: new things, beginners and renewal."""
import json
from pathlib import Path
from lesson_authoring import entry as E
H=[['拉丁 novus','新的']]
N=H+[['拉丁 novellus → 古法语 novel → 英语 novel〔形容词〕','新的、年轻的 → 新颖的']]
BOOK=H+[['拉丁 novellus / novella → 意大利 novella','新鲜事 → 故事、短篇叙事'],['英语 novel〔名词〕','小说；后来主要指长篇小说']]
IN=H+[['拉丁 in- + novāre → innovāre / innovātus','使更新、引入变化'],['英语 innovate','革新；引入新方法']]
REN=H+[['拉丁 re- + novāre → renovāre / renovātus','使重新变新'],['中古英语 renovate〔形容词〕→ 英语动词 renovate','更新过的 → 翻新、修复']]
ICE=H+[['拉丁 novīcius → 法语 novice → 英语 novice','新来的 → 初学者、初入修会者']]
def D(h,a,b):return h+[[a,b]]
W=[
E('novel','英 /ˈnɒvəl/；美 /ˈnɑːvəl/','新颖的；新奇的；长篇小说','新鲜、不按老路来的点子是 novel。小说义则经“新鲜故事”那条历史传来，不是所有小说内容都必须离奇。','形容词经古法语 novel；小说名词经意大利 novella。两路都接拉丁 novus、novellus，但不是英语形容词直接变成小说名词。',N+BOOK[1:],'a novel approach 是新颖做法；a historical novel 是历史小说。形容词常强调相对已有经验的新意，名词说作品类型。','a novel idea；a novel approach；read a novel。','new 只需新出现或新获得；novel 常含不同寻常的新意。小说也不能和所有 fiction 完全画等号。',('The team proposed a novel way to reduce waste.','团队提出了一种减少浪费的新办法。'),('She is reading a novel set in nineteenth-century Paris.','她正在读一本以十九世纪巴黎为背景的小说。'),sources=['https://www.etymonline.com/word/novel']),
E('innovation','/ˌɪnəˈveɪʃən/','创新；革新；新方法或新成果','把一种新做法带进原本的流程，让事情换一种方式运转，这就是 innovation 的中心。','后期拉丁 innovātiō，经法语或直接拉丁传入；英语名词出现早于 innovate，不画成后者的产物。',[H[0],['拉丁 innovāre → 后期拉丁 innovātiō；法语 innovation','更新、改变 → 革新'],['英语 innovation','创新过程；引入的新变化']],'可不可数地说鼓励 innovation，也可数 a useful innovation。它可以是技术、流程、服务等变化，不一定是一件刚发明的实体机器。','technological innovation；encourage innovation；an innovation in。','invention 常强调发明一个东西或方法；innovation 强调把新变化引入实践，两者可能重叠。',('The company encourages innovation in everyday work.','公司鼓励在日常工作中尝试新方法。'),('This small innovation made the process much easier.','这项小革新让流程轻松了许多。'),sources=['https://www.etymonline.com/word/innovation']),
E('innovative','英 /ˈɪnəvətɪv/；美 /ˈɪnəveɪtɪv/','富有创新性的；采用新办法的','遇到问题时会换个办法来做，或者某个方案确实带来了新的做法，就可称 innovative。','innovate + -ive；英语形容词构词。',D(IN,'英语 innovate + -ive → innovative','革新 → 善于或体现革新的'),'可形容人、团队、方案。常带赞许语气，但新颖本身不保证有效，仍要看具体效果。','an innovative design；an innovative approach；innovative thinking。','creative 侧重想象、创造力；innovative 更突出引入新方法或改变现有做法。',('The school adopted an innovative approach to teaching science.','学校采用了一种新颖的科学教学方法。'),('The design is innovative, but it still needs testing.','这个设计有新意，但仍需要测试。')),
E('nova','英 /ˈnəʊvə/；美 /ˈnoʊvə/','新星〔天文〕','原来看不明显的位置突然亮起来，古人仿佛看见一颗“新星”；名字记录的是看上去新出现。','拉丁 nova 是 novus 的阴性形式，与 stella“星”搭配；nova stella“新星”后来缩短为 nova。',[H[0],['拉丁 nova stella → 科学用语 nova','新的星 → 新星'],['现代天文 nova','恒星系统突然显著增亮的爆发现象']],'现代所说经典新星通常是白矮星吸积来的表层物质发生热核爆发，恒星遗骸本身仍存续。它不是一颗刚诞生的恒星。','a nova eruption；a recurrent nova；复数 novae 或 novas。','supernova 的物理过程与规模不同，不能简单理解成同一个普通新星稍微亮一点。',('The nova became bright enough to see without a telescope.','这颗新星变得足够明亮，不用望远镜也能看见。'),('Astronomers monitored the nova as it gradually faded.','天文学家监测着这颗新星逐渐变暗。'),sources=['https://en.wiktionary.org/wiki/nova#English','https://science.nasa.gov/mission/hubble/science/science-behind-the-discoveries/hubble-stellar-explosions/']),
E('renovation','/ˌrenəˈveɪʃən/','翻新；整修；更新工程','保留原来的房屋或设施，把磨损、过时的部分修整，让它重新好用，这个过程就是 renovation。','拉丁 renovātiō，经法语进入中古英语；与 renovate 对应，但名词并非从现代英语动词才造出来。',[H[0],['拉丁 renovāre → renovātiō → 法语 renovation','使重新变新 → 修整、更新'],['中古英语 → renovation','翻新过程或工程']],'常见房屋、学校、博物馆的整修。翻新可以改得很多，也可以较有限，不必意味着拆掉重建。','under renovation；a major renovation；home renovation。','repair 修某个损坏；renovation 常指较整体的整修更新，可能包含多项维修。',('The library is closed for renovation.','图书馆因翻修而关闭。'),('The renovation preserved the original staircase.','这次翻新保留了原来的楼梯。')),
E('novelty','英 /ˈnɒvəlti/；美 /ˈnɑːvəlti/','新奇；新鲜感；新奇的小玩意','一件事刚出现，让你忍不住多看两眼，这份“以前没碰过”的感觉就是 novelty。','古法语 novelté，接 novel“新的”，再上溯拉丁 novellus；现代可联系 novel + -ty。',[H[0],['拉丁 novellus → 古法语 novel / novelté','新的 → 新鲜、新奇'],['中古英语 → novelty','新鲜感；新奇物品']],'the novelty wears off 是新鲜感过去了；novelty gifts 是供趣味、逗乐的小礼物。新奇不保证实用或持久。','the novelty of；novelty wears off；a novelty item。','innovation 常强调引入新做法；novelty 可以只是新鲜有趣，未必改变实际工作方式。',('The novelty of working from home soon wore off.','在家工作的新鲜感很快就过去了。'),('The shop sells novelty mugs shaped like animals.','这家店出售做成动物形状的新奇马克杯。')),
E('novice','英 /ˈnɒvɪs/；美 /ˈnɑːvɪs/','新手；初学者；初入修会者','刚踏进一个领域，还没积累多少经验的人，就像队伍里的新面孔。','拉丁 novīcius“新来的”，经法语 novice 传入。',ICE,'a novice driver 是新手司机；a novice at chess 是下棋初学者。宗教语境有正式的初学修会成员义，不能一律译成一般学生。','a complete novice；a novice at；novice users。','amateur 主要是非职业身份；novice 强调经验少，业余爱好者也可能十分熟练。',('The instructions are clear enough for a complete novice.','说明写得很清楚，完全的新手也能看懂。'),('She is still a novice at sailing.','她在帆船驾驶方面还只是新手。')),
E('innovate','/ˈɪnəveɪt/','创新；革新；引入新方法','不只是想一个漂亮点子，而是试着让原有做法换成新的运转方式。','借拉丁 innovātus，接 innovāre“更新、改变”；in- 与 novāre 组合。',IN,'常作不及物动词，如 innovate in education、continue to innovate；也可有及物用法。日常表达中不必为了显得正式而把任何小修改都叫 innovate。','innovate in；innovate to solve problems；the ability to innovate。','renovate 多把已有东西修整更新；innovate 多引入新想法、方法，两者都含“新”但动作不同。',('Small teams can innovate quickly when they can test ideas freely.','小团队能自由试验想法时，创新速度可以很快。'),('The organisation needs to innovate in how it delivers services.','该组织需要在提供服务的方式上革新。'),sources=['https://www.etymonline.com/word/innovate']),
E('novella','英 /nəˈvelə/；美 /noʊˈvelə/','中篇小说','它和 novel 都从“新鲜故事”来；现代文学分类中，novella 常处在短篇与长篇之间。','借意大利 novella，接拉丁 novellus / novella；与 novel 名词是不同时间传入的同源词。',[H[0],['拉丁 novellus / novella → 意大利 novella','新的、新鲜事 → 故事'],['英语 novella','中篇小说']],'一般比 short story 长、比 novel 短，篇幅界线会随出版或奖项规则变化，不能把某个字数当作全英语统一标准。','a novella by；a collection of novellas；a short novella。','novel 是长篇小说，novella 常是中篇；二者的区别通常不在于谁更“新”。',('The novella can be read in a single evening.','这部中篇小说一个晚上就能读完。'),('The collection contains two novellas and several short stories.','这本集子收录了两部中篇小说和几篇短篇小说。')),
]
W.extend([
E('renovate','/ˈrenəveɪt/','翻新；整修；使恢复活力','旧房子不必推倒，把坏的修好、过时的更新，让它重新可用，就是 re- 的“再”加 nov- 的“新”。','拉丁 renovātus 曾以形容词形式进入中古英语，后来作英语动词；接 re- + novāre。',REN,'常说 renovate a house、renovate a kitchen。现代用途集中在建筑设施更新，也能较正式地比喻使某事恢复活力。','renovate a building；renovate the kitchen；a renovated apartment。','decorate 主要装饰；renovate 可以涉及功能与结构整修，不只是换颜色。',('They renovated the old house before moving in.','他们先翻新了旧房子，再搬进去住。'),('The school plans to renovate its science laboratories.','学校计划整修科学实验室。'),sources=['https://www.merriam-webster.com/dictionary/renovate','https://en.wiktionary.org/wiki/renovate#English']),
E('innovator','英 /ˈɪnəveɪtə/；美 /ˈɪnəveɪtər/','创新者；引入新做法的人','一个人让大家开始用不同的方式做事，可能是工具、流程或观念上的改变，他就可以是 innovator。','后期拉丁 innovātor，来自 innovāre；现代能分析为 innovate 与 -or，但历史上有拉丁施事名词来源。',[H[0],['拉丁 innovāre → 后期拉丁 innovātor','革新 → 引入变化的人'],['英语 innovator','创新者']],'这个词可说艺术、商业、教育等领域的人，不仅限于技术发明家。创新也可能来自团队，不一定归功于一个孤立天才。','an innovator in；a leading innovator；design innovators。','inventor 更突出发明；innovator 更广，可以是把已有东西组合成新做法的人。',('She became an innovator in accessible design.','她成了无障碍设计领域的创新者。'),('The exhibition celebrates several innovators in film editing.','展览向几位电影剪辑领域的创新者致敬。'),sources=['https://www.etymonline.com/word/innovator']),
E('novitiate','/nəˈvɪʃiət/','初学修会阶段；初学者培养处；初学修会者','novice 是新进入修会的人，novitiate 则常把镜头拉到这段接受培养、了解生活规则的时期。','中古法语 noviciat 或中世纪拉丁 noviciātus，接拉丁 novīcius；是身份、阶段名词的借入。',[H[0],['拉丁 novīcius → 中世纪拉丁 noviciātus；法语 noviciat','新入者 → 初学修会身份、时期'],['英语 novitiate','初学阶段；培养场所；初学者']],'常见 enter 或 complete the novitiate。还可指初学者生活学习的地方，有时指初学者本人；具体制度因修会传统而异。','enter the novitiate；complete a novitiate；a year of novitiate。','novice 直接指人；novitiate 常指阶段或培养安排，虽有指人义，阅读时要看句子。',('She entered the novitiate after a period of reflection.','经过一段时间思考后，她进入了修会初学阶段。'),('The letter describes daily life in the novitiate.','信中描述了初学修会阶段的日常生活。')),
E('novation','英 /nəʊˈveɪʃən/；美 /noʊˈveɪʃən/','债的更新；以新义务或新合同关系替代旧关系〔法律〕','不是在旧文件上随便改个字，而是让新的义务关系接替旧的，旧关系相应解除。','拉丁 novātiō“更新”，接 novāre“使新”；借入后用于法律上的替代更新。',[H[0],['拉丁 novāre → novātiō → 英语 novation','使新 → 更新；法律关系的替代']],'法律英语里常见合同当事人或义务的替换。核心是新关系替代旧关系，具体成立条件由适用规则决定；这里先掌握阅读时的词义。','a novation agreement；novation of a contract；by novation。','amendment 是修改；assignment 常涉及权利转让；novation 强调新关系取代并解除旧关系，不能直接互换。',('The document explains how the new agreement effects a novation.','文件解释了新协议如何构成对旧关系的替代更新。'),('The parties discussed a novation when a new contractor joined the project.','新承包商加入项目时，各方讨论了合同关系的替代安排。'),sources=['https://en.wiktionary.org/wiki/novation#English','https://www.law.cornell.edu/wex/novation']),
E('renovator','英 /ˈrenəveɪtə/；美 /ˈrenəveɪtər/','翻修者；翻新施工者或机构','renovate 是把旧东西修整更新，renovator 就是具体承担这份工作的人或机构。','renovate + -or；英语施事名词。',D(REN,'英语 renovate + -or → renovator','翻新 → 从事翻新的人'),'常见房屋维修、整修语境，也可用于更新旧物的从业者。词本身不说明其资质、工种或规模。','a home renovator；an experienced renovator；hire a renovator。','builder 泛指建造者；renovator 更突出改造已有建筑或物件，而不是从无到有建一个。',('The renovator kept the original wooden doors.','翻修施工者保留了原来的木门。'),('They asked an experienced renovator to inspect the house.','他们请一位有经验的翻修人员查看了房子。')),
E('innovatory','英 /ˈɪnəvətəri/','创新的；有革新性的〔较多见于英式英语〕','它把“带来新做法”的特点放到方法或项目上，与 innovative 的核心意思很接近。','innovate + -ory；英语形容词构词。',D(IN,'英语 innovate + -ory → innovatory','创新 → 具有革新性的'),'在英式正式文字中会碰到。与 innovative 没有一条适用于所有句子的硬性意义分界，日常优先认熟 innovative 即可。','innovatory methods；an innovatory programme。','innovative 更普遍；innovatory 是相近的另一种形容词，不必硬编成“一个讲思想、一个讲行动”。',('The report describes an innovatory programme for adult education.','报告介绍了一项有创新性的成人教育项目。'),('The school combined traditional and innovatory teaching methods.','学校把传统方法和创新教学方法结合起来。'),sources=['https://www.merriam-webster.com/dictionary/innovatory','https://en.wiktionary.org/wiki/innovatory#English']),
E('innovational','/ˌɪnəˈveɪʃənəl/','与创新有关的；具有创新倾向的〔少用〕','innovation 是创新活动，加 -al 后可以谈围绕这种活动的政策、能力或特点。','innovation + -al；以英语名词为基础构成形容词。',[H[0],['拉丁 innovāre → innovātiō → 英语 innovation','更新 → 创新'],['英语 innovation + -al → innovational','与创新相关的']],'偏正式、较少用。有时也表示富有创新性，与 innovative 重叠；不能硬把它只限定成“与创新有关但自己没有新意”。','innovational capacity；innovational activity。','innovative 通常更简洁常见；innovational 多在讨论创新活动、能力的文字里出现。',('The paper examines the innovational capacity of small firms.','论文研究了小企业的创新能力。'),('The policy aims to support innovational activity across the region.','这项政策旨在支持整个地区的创新活动。'),sources=['https://www.merriam-webster.com/dictionary/innovational']),
E('renovative','/ˈrenəveɪtɪv/','有更新、修复作用的；翻新性的〔少用〕','renovate 做的是更新修整，renovative 则强调某项工作具有这种恢复、使之焕新的作用。','renovate + -ive；英语形容词构词。',D(REN,'英语 renovate + -ive → renovative','翻新、恢复 → 有更新修复作用的'),'较少见，正式文字可修饰措施、工作等。日常谈装修工程时，renovation work 往往更自然常用。','renovative work；renovative measures。','innovative 引入新办法；renovative 重点在恢复、修整已有事物，二者的新意方向不同。',('The report outlines the renovative work needed to reopen the hall.','报告概述了大厅重新开放所需的整修工作。'),('The essay praises the renovative influence of public support on the institution.','文章赞扬了公众支持对该机构恢复活力的作用。'),sources=['https://www.merriam-webster.com/dictionary/renovative']),
E('novelist','英 /ˈnɒvəlɪst/；美 /ˈnɑːvəlɪst/','小说家；长篇小说作者','novel 是长篇小说，-ist 把镜头移到经常创作这类作品的人身上。','novel + -ist；英语名词派生。',D(BOOK,'英语 novel + -ist → novelist','长篇小说 → 小说家'),'主要按作品类型称呼作者，不表示他只能写小说，也不保证作品一定畅销或题材特别新奇。','a historical novelist；a debut novelist；a successful novelist。','writer 范围很广；novelist 具体说小说创作，尤其长篇小说。',('The novelist spent years researching the setting of her book.','这位小说家花了多年研究作品的背景。'),('He is known as a novelist, though he also writes essays.','他以小说家的身份为人所知，不过也写散文。')),
])
